using System;using System.IO;using System.Linq;using System.Security.Cryptography;using Mono.Cecil;using DuelStructureMonoAccess;
class MonoAccessSmoke {
 static string Hash(string f){using(var h=SHA256.Create())return Convert.ToBase64String(h.ComputeHash(File.ReadAllBytes(f)));}
 static void Main(string[] args){string original=args[0],plugin=args[1],dest=args[2];var hash=Hash(original);var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(Path.GetDirectoryName(original));int privateBefore,privateAfter;using(var assembly=AssemblyDefinition.ReadAssembly(original,new ReaderParameters{AssemblyResolver=resolver})){privateBefore=assembly.MainModule.Types.Sum(t=>t.Fields.Count(f=>f.IsPrivate));Patcher.Apply(assembly,plugin);privateAfter=assembly.MainModule.Types.Sum(t=>t.Fields.Count(f=>f.IsPrivate));if(Patcher.Promoted<=0||privateAfter<=0||privateAfter>=privateBefore)throw new Exception("Member access promotion is not scoped");Directory.CreateDirectory(Path.GetDirectoryName(dest));assembly.Write(dest);}if(Hash(original)!=hash)throw new Exception("Original body was modified");var checkedResolver=new DefaultAssemblyResolver();checkedResolver.AddSearchDirectory(Path.GetDirectoryName(dest));checkedResolver.AddSearchDirectory(Path.GetDirectoryName(original));int members=0;using(var module=ModuleDefinition.ReadModule(plugin,new ReaderParameters{AssemblyResolver=checkedResolver})){foreach(var reference in module.GetMemberReferences()){var scope=reference.DeclaringType.GetElementType().Scope as AssemblyNameReference;if(scope==null||scope.Name!="Assembly-CSharp")continue;var field=reference as FieldReference;var method=reference as MethodReference;if(field!=null){var def=field.Resolve();if(def==null||!def.IsPublic)throw new Exception("Inaccessible field: "+reference.FullName);}if(method!=null){var def=method.Resolve();if(def==null||!def.IsPublic)throw new Exception("Inaccessible method: "+reference.FullName);}members++;}}Console.WriteLine("SUCCESS "+members+" MDPro3 member references are accessible; "+Patcher.Promoted+" required members promoted in memory, original body preserved");}
}
